#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> block_sums(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(T) - 1) / static_cast<std::size_t>(T);
        const std::size_t start = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end = (start + chunk < n) ? (start + chunk) : n;

        long long local_sum = 0;
        if (start < end) {
            for (std::size_t i = start; i < end; ++i) {
                local_sum += x[i];
            }
        }
        block_sums[tid] = local_sum;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += block_sums[t];
        }

        if (start < end) {
            long long running = offset;
            for (std::size_t i = start; i < end; ++i) {
                running += x[i];
                output[i] = static_cast<int>(running);
            }
        }
    }
}
